<?php declare(strict_types=1);namespace Interferencia\Modules\Moodle;use PDO;use RuntimeException;final readonly class EnrollmentRepository{public function __construct(private PDO$database){}public function all(array$unitIds):array{if($unitIds===[])return[];$marks=implode(',',array_fill(0,count($unitIds),'?'));$s=$this->database->prepare("SELECT e.*,f.name student_name,f.cpf_cnpj,m.fullname course_name,m.shortname,p.name product_name,COALESCE(e.final_value,p.value) value,p.max_installments,c.name campaign_name,u.name unit_name,a.name attendant_name FROM student_enrollments e INNER JOIN finance_customers f ON f.id=e.finance_customer_id INNER JOIN moodle_courses m ON m.id=e.moodle_course_id LEFT JOIN finance_products p ON p.id=e.finance_product_id LEFT JOIN finance_campaigns c ON c.id=e.campaign_id INNER JOIN units u ON u.id=e.unit_id LEFT JOIN users a ON a.id=e.attendant_user_id WHERE e.unit_id IN ($marks) ORDER BY e.created_at DESC,e.id DESC LIMIT 500");$s->execute($unitIds);return$s->fetchAll();}public function create(int$customerId,int$productId,?int$campaignId,int$unitId,int$creatorId,int$attendantId,array$allowedUnits):int{if(!in_array($unitId,$allowedUnits,true))throw new RuntimeException('Selecione uma unidade permitida.');if($productId<1)throw new RuntimeException('Selecione o curso contratado.');$s=$this->database->prepare('SELECT COUNT(*) FROM finance_customers WHERE id=:id AND unit_id=:unit AND is_deleted=0');$s->execute(['id'=>$customerId,'unit'=>$unitId]);if((int)$s->fetchColumn()!==1)throw new RuntimeException('Aluno não encontrado nesta unidade.');$s=$this->database->prepare('SELECT value,moodle_course_id FROM finance_products WHERE id=:id AND is_active=1 AND value>=5 AND moodle_course_id IS NOT NULL AND (unit_id=:unit OR unit_id IS NULL)');$s->execute(['id'=>$productId,'unit'=>$unitId]);$product=$s->fetch();if(!is_array($product))throw new RuntimeException('Curso contratado inválido ou ainda não configurado.');$courseId=(int)$product['moodle_course_id'];$base=(float)$product['value'];$discount=0.0;if($campaignId!==null){$s=$this->database->prepare('SELECT discount_percent FROM finance_campaigns WHERE id=:id AND is_active=1 AND valid_until>=CURRENT_DATE');$s->execute(['id'=>$campaignId]);$found=$s->fetchColumn();if($found===false)throw new RuntimeException('Campanha inválida ou expirada.');$discount=(float)$found;}$final=round($base*(1-$discount/100),2);if($final<5)throw new RuntimeException('O desconto deixa a cobrança abaixo do valor mínimo de R$ 5,00.');$s=$this->database->prepare('INSERT INTO student_enrollments(finance_customer_id,moodle_course_id,finance_product_id,campaign_id,base_value,discount_percent,final_value,unit_id,attendant_user_id,created_by) VALUES(:customer,:course,:product,:campaign,:base,:discount,:final,:unit,:attendant,:creator)');$s->execute(['customer'=>$customerId,'course'=>$courseId,'product'=>$productId,'campaign'=>$campaignId,'base'=>$base,'discount'=>$discount,'final'=>$final,'unit'=>$unitId,'attendant'=>$attendantId,'creator'=>$creatorId]);return(int)$this->database->lastInsertId();}public function chargeContext(int$id,array$units):?array{if($units===[])return null;$marks=implode(',',array_fill(0,count($units),'?'));$s=$this->database->prepare("SELECT e.*,p.name product_name,COALESCE(e.final_value,p.value) value,p.max_installments,c.name campaign_name FROM student_enrollments e INNER JOIN finance_products p ON p.id=e.finance_product_id LEFT JOIN finance_campaigns c ON c.id=e.campaign_id WHERE e.id=? AND e.unit_id IN ($marks) AND e.finance_payment_id IS NULL LIMIT 1");$s->execute(array_merge([$id],$units));$row=$s->fetch();return is_array($row)?$row:null;}public function attachPayment(int$id,int$paymentId):void{$s=$this->database->prepare("UPDATE student_enrollments SET finance_payment_id=:payment,status='awaiting_payment' WHERE id=:id AND finance_payment_id IS NULL");$s->execute(['payment'=>$paymentId,'id'=>$id]);}}
